scwin.trigger1_onclick = function(e) {
    //		windowContainer1.createWindow( "aaa" , "" , "http://www.daum.net" , "abc" , "ccccc" , "" , "" , "tooltip" );
    //		setTimeout(() => {
    $p.parent().windowContainer1.createWindow("bbb", "", "windowContainer_processMsgFrame_WESD-612_(WSQ-4699)_sub.xml", "bbb", "bbbb", "", "", "bbbb");
    WebSquare.event.stopPropagation(e);
    //		}, 0);
