scwin.trigger2_onclick = function(e) {
    $p.executeSubmission("submission1");
};
scwin.trigger3_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");} //팝업을 사용하기 위해 반드시 포함되어야 한다.
    // 실제 전달할 데이터 정의 
    var rowJSON = {
        "Personal Info": {
            "Name": "Lee",
            "Age": 50,
            "Married": false
        },
        "Region": "Seoul",
        "Carrier": true
    };
    // 새로 열릴 화면에 데이터를 전달 (dataObject를 통해 전달 가능)
    var dataObject = {
        "type": "json", // 데이터 타입. "json" 권장 
        "name": "paramTest", // 데이터를 가져오기 위한 key 값. popup에서 $p.getParameter( "paramTest" )로 깨내올 수 있음.
        "data": rowJSON // 실제 전달할 데이터
    };
    /*	     
    	options.modal
    	<String:N>
    	[default: false] modal을 이용해서 뒤 쪽 배경을 동작하지 않도록 만들기 위한 인자. false이면 뒤쪽의 컴포넌트 사용 가능.

    	options.frameModal
    	<String:N>
    	[default: ""] modal을 표시해줄 frame(wframe, tabControl, windowContainer)을 지정. "top", "parent", "frame", frame id

    	options.processMsgFrame
    	<Object:N>
    	[default: false] wframePopup인 경우 processMessage를 popup 내부에 띄울지에 대한 설정.
    */
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: "400px",
        height: "300px",
        top: "130px",
        left: "200px",
        popupName: "테스트 팝업",
        modal: false,
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        dataObject: dataObject,
        title: "false",
        processMsgFrame: "true"
    };
    // 팝업 생성.
    $p.openPopup("windowContainer_processMsgFrame_WESD-612_(WSQ-4699)_sub.xml", options);
};
scwin.trigger4_onclick = function(e) {
    // id가 a,b,c,d,e인 5개 컬럼이 존재하는 dataList
    var options = {
        common: {
            fileName: "user.xlsx",
            showProcess: true,
            multipleSheet: true,
            printSet: {
                landScape: "true",
                fitToPage: "true",
                fitWidth: "1",
                fitHeight: "1",
                scale: "222"
            }
        },
        excelInfo: [{
            gridId: $p.getComponentById("gridView1").getID(),
            sheetName: "첫번째 sheet",
            //		            removeColumns : "1,3",
            //		            foldColumns : "2",
            //		            startRowIndex : 3,
            //		            startColumnIndex : 0,
            headerColor: "#DBEEF3",
            bodyColor: "#92CDDC",
            wframeId: "popup1",
            infoArr: [{
                rowIndex: 1,
                colIndex: 3,
                rowSpan: 1,
                colSpan: 2,
                text: "데이터표시",
                textAlign: "center"
            }]
        }]
    };
    //		WebSquare.util.multipleDataListDownload( options );		
    WebSquare.util.multipleExcelDownload(options)
};
scwin.trigger5_onclick = function(e) {
    // id가 a,b,c,d,e인 5개 컬럼이 존재하는 dataList
    var options = {
        common: {
            fileName: "user.xlsx",
            showProcess: true,
            multipleSheet: true,
            printSet: {
                landScape: "true",
                fitToPage: "true",
                fitWidth: "1",
                fitHeight: "1",
                scale: "222"
            }
        },
        excelInfo: [{
            dataListId: $p.getComponentById("dataList1").getID(),
            sheetName: "첫번째 sheet",
            removeColumns: "1,3",
            foldColumns: "2",
            startRowIndex: 3,
            startColumnIndex: 0,
            headerColor: "#DBEEF3",
            bodyColor: "#92CDDC",
            wframeId: "wframe1",
            infoArr: [{
                rowIndex: 1,
                colIndex: 3,
                rowSpan: 1,
                colSpan: 2,
                text: "데이터표시",
                textAlign: "center"
            }]
        }]
    };
    $p.multipleDataListDownload(options);
};
